// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed parameters: from address, caddress (we will pass a recording helper), dynamic array length and values
    function testFuzz_property(address from, uint256 seed, uint8 tosLen) public {
        // keep tosLen in a reasonable bound but allow zero to be excluded by vm.assume below
        tosLen = tosLen % 8; // limit to small arrays for practicality
        // require non-empty per contract requirement
        vm.assume(tosLen > 0);

        // construct fuzzed _tos and v arrays derived from seed
        address[] memory tos = new address[](tosLen);
        uint256[] memory v = new uint256[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // derive addresses from seed to get varied EOAs
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, block.timestamp)))));
            v[i] = uint256(keccak256(abi.encodePacked(seed, i))) % 1 ether;
        }

        // Deploy a recording helper that matches the selector transferFrom(address,address,uint256)
        // so that c's external calls are observable. This helper will always succeed.
        Recorder rec = new Recorder();

        // call c.transfer and observe whether it completes or reverts via try/catch
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL FACT: For the reference contract, transfer(...) never reverts when _tos.length > 0.
        // The mutant replaces the final `return true;` with a `revert(...)`, so for some inputs the mutant will cause ok==false.
        // Assert that the call completed successfully (this holds for the reference for all admissible inputs).
        assertTrue(ok);

        // Additionally, ensure that the recorder observed the same number of incoming calls as tosLen
        // (sanity check that c indeed attempted the external calls in the reference implementation).
        // This secondary check reads only the recorder's public getter which is allowed.
        assertTrue(rec.callCount() == tosLen);
    }
}

contract Recorder {
    uint public callCount;
    struct Call { address from; address to; uint256 amount; }
    Call[] public calls;

    // define the exact signature c encodes: transferFrom(address,address,uint256)
    function transferFrom(address _from, address _to, uint256 _amount) external returns (bool) {
        callCount++;
        calls.push(Call({from: _from, to: _to, amount: _amount}));
        return true;
    }

    // accessor for array length (automatically public for calls, but provide explicit)
    function callsLength() external view returns (uint) { return calls.length; }
}
